    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
def find_block(g,bg):
    H,W=len(g),len(g[0])
    rects=[]
    for v in set(x for row in g for x in row):
        if v==bg: continue
        cs={(r,c) for r in range(H) for c in range(W) if g[r][c]==v}
        rs={r for r,c in cs}; cc={c for r,c in cs}
        if len(cs)==len(rs)*len(cc): rects.append((v,min(rs),max(rs),min(cc),max(cc)))
    return max(rects,key=lambda kv:(-(kv[2]-kv[1]),-(kv[4]-kv[3])))
def f(g):
