    block=find_block(g,bg); br,bro,bc,bco=block[1:]
    def blk(r,c): return br<=r<=bro and bc<=c<=bco
    out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==bg or blk(r,c): continue
            for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
