    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
# Full-column paint rule: marker paints ALL block cells in its row/col direction line. Let's verify on all demos.
def f(g):
    H,W=len(g),len(g[0]); cnt=Counter(x for row in g for x in row); bg=cnt.most_common(1)[0][0]
    rects=[]
    for v in set(cnt):
        if v==bg: continue
        cs={(r,c) for r in range(H) for c in range(W) if g[r][c]==v}
        rs={r for r,c in cs}; cc={c for r,c in cs}
        if len(cs)==len(rs)*len(cc) and len(cs)>1: rects.append((v,min(rs),max(rs),min(cc),max(cc)))
    block=max(rects,key=lambda kv:(-(kv[4]-kv[3]),-(kv[2]-kv[1])))
    br,bro,bc,bco=block[1:]
    def blk(r,c): return br<=r<=bro and bc<=c<=bco
    out=[row[:] for row in [list(row) for row in g]]
    for r in range(H):
        for c in range(W):
            v=out[r][c]
            if v==bg or blk(r,c): continue
            # ray in 4 directions; when hitting block, PAINT all consecutive block cells in that direction
            for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                y,x=r+dy,c+dx
                while 0<=y<H and 0<=x<W:
                    if blk(y,x):
                        out[y][x]=v
                        y+=dy;x+=dx
                        continue
                    elif out[y][x]==bg: y+=dy;x+=dx
                    else: break
    return out
